import{_ as o,C as n,o as t,c as i,a2 as r,b as s,w as e,a as h,E as g,a3 as d}from"./chunks/framework.CZGNF-7T.js";const p=JSON.parse('{"title":"IBS 워크스페이스 소개","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1788431732000}'),u={name:"index.md"};function E(m,a,c,A,B,C){const l=n("Mermaid");return t(),i("div",null,[a[1]||(a[1]=r('<h1 id="ibs-워크스페이스-소개" tabindex="-1">IBS 워크스페이스 소개 <a class="header-anchor" href="#ibs-워크스페이스-소개" aria-label="Permalink to &quot;IBS 워크스페이스 소개&quot;">​</a></h1><blockquote><p><strong>IBS (Intelligent Business System) 워크스페이스</strong>는 부동산 개발사업의 전 생애주기에서 발생하는 자금, 계약, 고객, 부지, 회계, 전자결재, 소송 등 핵심 데이터를 통합 관리하고 협업하는 <strong>디벨로퍼를 위한 지능형 업무 플랫폼</strong>입니다.</p></blockquote><p>글로벌 협업 표준인 <strong>레드마인 (Redmine)</strong> 엔진과 체계적인 <strong>데이터 파이프라인</strong>을 결합하여, 단순한 데이터 기록을 넘어 모든 업무와 의사결정을 유기적으로 연결하고 자산화합니다.</p><h2 id="시스템-핵심-아키텍처" tabindex="-1">시스템 핵심 아키텍처 <a class="header-anchor" href="#시스템-핵심-아키텍처" aria-label="Permalink to &quot;시스템 핵심 아키텍처&quot;">​</a></h2><p>IBS는 독립된 업무 영역을 하나의 맥락으로 연결하여 데이터 무결성과 신속한 의사결정을 지원합니다.</p>',5)),(t(),s(d,null,{default:e(()=>[g(l,{id:"mermaid-17",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%F0%9F%8F%97%EF%B8%8F%20%ED%94%84%EB%A1%9C%EC%A0%9D%ED%8A%B8%2F%EB%B6%80%EC%A7%80%20%EC%84%A4%EC%A0%95%5D%20--%3E%20B%5B%F0%9F%A4%9D%20%EB%B6%84%EC%96%91%20%EA%B3%84%EC%95%BD%20%26%20CRM%5D%0AB%20--%3E%20C%5B%F0%9F%92%B0%20%EB%8C%80%EA%B8%88%20%EC%88%98%EB%82%A9%20%26%20%EA%B3%A0%EC%A7%80%5D%0AC%20--%3E%20D%5B%F0%9F%93%8A%20%ED%9A%8C%EA%B3%84%20%EA%B2%B0%EC%82%B0%20%26%20%EC%98%88%EC%82%B0%20%ED%86%B5%EC%A0%9C%5D%0A%0Asubgraph%20%EC%A0%84%EC%82%AC%20%ED%98%91%EC%97%85%20%26%20%EC%9D%98%EC%82%AC%EA%B2%B0%EC%A0%95%0AE%5B%F0%9F%8E%AF%20%EC%9D%B4%EC%8A%88%2F%EB%A1%9C%EB%93%9C%EB%A7%B5%5D%20%3C--%3E%20F%5B%F0%9F%93%9D%20%ED%9A%8C%EC%9D%98%EB%A1%9D%20%26%20%EC%95%A1%EC%85%98%EC%95%84%EC%9D%B4%ED%85%9C%5D%0AF%20%3C--%3E%20G%5B%F0%9F%93%91%20%EC%A0%84%EC%9E%90%EA%B2%B0%EC%9E%AC%2017%EC%A2%85%5D%0Aend%0A%0AD%20%3C--%3E%20G%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="왜-ibs-워크스페이스인가" tabindex="-1">왜 IBS 워크스페이스인가? <a class="header-anchor" href="#왜-ibs-워크스페이스인가" aria-label="Permalink to &quot;왜 IBS 워크스페이스인가?&quot;">​</a></h2><ul><li><strong>친숙하고 강력한 협업 환경</strong> - 레드마인 기반의 이슈 트래킹 및 회의록 연동으로 업무의 생성부터 완료까지 체계적으로 관리합니다.</li><li><strong>도메인 결합형 통합 데이터 관리</strong> - 부지, 상품, 계약, 수납, 회계가 단일 데이터 파이프라인으로 연결되어 데이터 불일치와 누락을 원천 차단합니다.</li><li><strong>의사결정의 지식 자산화</strong> - 회의 의제, 결정 사항, 전자결재 품의 이력이 실제 업무 (Issue)와 연결되어 조직의 영구적인 지식 자산으로 축적됩니다.</li><li><strong>신속한 경영 의사결정</strong> - 실시간 대시보드를 통해 사업 수지, 자금 현황, 리스크를 한눈에 파악하고 선제적으로 대응할 수 있습니다.</li></ul><h2 id="주요-기능-및-매뉴얼-안내" tabindex="-1">주요 기능 및 매뉴얼 안내 <a class="header-anchor" href="#주요-기능-및-매뉴얼-안내" aria-label="Permalink to &quot;주요 기능 및 매뉴얼 안내&quot;">​</a></h2><h3 id="🎯-1-업무-관리-및-협업-redmine-engine" tabindex="-1">🎯 1. 업무 관리 및 협업 (Redmine Engine) <a class="header-anchor" href="#🎯-1-업무-관리-및-협업-redmine-engine" aria-label="Permalink to &quot;🎯 1. 업무 관리 및 협업 (Redmine Engine)&quot;">​</a></h3><ul><li><strong><a href="/work-manage/workspace.html">워크스페이스</a></strong>: 전사, 본사 부서, 프로젝트 단위 협업 공간 구성</li><li><strong><a href="/work-manage/meeting.html">회의록 관리</a></strong>: 회의 의제, 결정 사항, 후속 조치 (Action Item) 연동 자산화</li><li><strong><a href="/work-manage/issue.html">업무 및 로드맵</a></strong>: 로드맵, 사용자 맞춤형 업무 할당 및 이력 추적</li><li><strong><a href="/work-manage/calendar.html">캘린더 &amp; 게시판</a></strong>: 마일스톤 일정 공유 및 부서 간 소통 포럼</li></ul><h3 id="📑-2-전자결재-시스템-approval" tabindex="-1">📑 2. 전자결재 시스템 (Approval) <a class="header-anchor" href="#📑-2-전자결재-시스템-approval" aria-label="Permalink to &quot;📑 2. 전자결재 시스템 (Approval)&quot;">​</a></h3><ul><li><strong><a href="/approval/draft.html">기안 작성 및 17종 양식</a></strong>: 일반품의, 지출결의, 계약/법무 등 최적화된 서식 제공</li><li><strong><a href="/approval/route.html">자동 결재선 및 전결 규칙</a></strong>: 부서 조직도 기반 결재선 자동 산출 및 금액별 전결 처리</li><li><strong><a href="/approval/action.html">결재 처리 및 위임</a></strong>: 웹/모바일 승인·반려 및 대결 (위임) 관리</li><li><strong><a href="/approval/boxes.html">문서함 및 전자직인 PDF</a></strong>: 문서번호 자동 채번, 공람 및 법적 효력의 공식 PDF 출력</li></ul><h3 id="🏗️-3-사업지-및-마스터플랜-설정" tabindex="-1">🏗️ 3. 사업지 및 마스터플랜 설정 <a class="header-anchor" href="#🏗️-3-사업지-및-마스터플랜-설정" aria-label="Permalink to &quot;🏗️ 3. 사업지 및 마스터플랜 설정&quot;">​</a></h3><ul><li><strong><a href="/project/">프로젝트 등록 및 설정</a></strong>: 프로젝트 기본 정보 및 기초 데이터 설정 관리</li><li><strong><a href="/project/units.html">상품 및 유닛 구성</a></strong>: 동·호수 배치, 유닛 차수, 타입 및 층별 공급가 관리</li><li><strong><a href="/project/site-manage.html">부지 정보 관리</a></strong>: 필지별 토지 소유 현황, 토지주 상담 및 매입 계약 관리</li></ul><h3 id="🤝-4-분양-계약-및-고객-관리-crm" tabindex="-1">🤝 4. 분양 계약 및 고객 관리 (CRM) <a class="header-anchor" href="#🤝-4-분양-계약-및-고객-관리-crm" aria-label="Permalink to &quot;🤝 4. 분양 계약 및 고객 관리 (CRM)&quot;">​</a></h3><ul><li><strong><a href="/contract/">계약 등록 및 상세</a></strong>: 계약자 정보 통합 관리 및 옵션 계약 관리</li><li><strong><a href="/contract/status.html">동·호수 배치 현황</a></strong>: 분양 상태 시각화 및 분양률 실시간 집계</li><li><strong><a href="/contract/release.html">계약 변경 관리</a></strong>: 권리의무 승계, 계약 해제 및 부적격자 처리</li></ul><h3 id="💰-5-대금-수납-및-고객-고지" tabindex="-1">💰 5. 대금 수납 및 고객 고지 <a class="header-anchor" href="#💰-5-대금-수납-및-고객-고지" aria-label="Permalink to &quot;💰 5. 대금 수납 및 고객 고지&quot;">​</a></h3><ul><li><strong><a href="/payment/">수납 처리 및 집계</a></strong>: 회차별 납부 일정, 입금 매칭, 연체료 자동 계산</li><li><strong><a href="/notice/bill.html">수납 고지서 및 SMS</a></strong>: 맞춤형 수납 고지서 출력 및 알림 문자 발송</li></ul><h3 id="📊-6-회계-자금-관리-및-사업-수지" tabindex="-1">📊 6. 회계 자금 관리 및 사업 수지 <a class="header-anchor" href="#📊-6-회계-자금-관리-및-사업-수지" aria-label="Permalink to &quot;📊 6. 회계 자금 관리 및 사업 수지&quot;">​</a></h3><ul><li><strong><a href="/ledger/status.html">자금 출납 및 정산</a></strong>: 계좌별 거래 내역, 본사/프로젝트 운영비 관리</li><li><strong><a href="/project/budgets.html">예산 통제 및 수지 분석</a></strong>: 예산 대비 실제 집행 실적 (Actuals) 실시간 비교 및 캐시플로우 분석</li></ul><h3 id="⚖️-7-문서-보관소-및-소송-관리" tabindex="-1">⚖️ 7. 문서 보관소 및 소송 관리 <a class="header-anchor" href="#⚖️-7-문서-보관소-및-소송-관리" aria-label="Permalink to &quot;⚖️ 7. 문서 보관소 및 소송 관리&quot;">​</a></h3><ul><li><strong><a href="/document/">일반 문서 관리</a></strong>: 프로젝트별 중요 인허가 및 공문서 통합 보관</li><li><strong><a href="/document/legal-case.html">소송 사건 관리</a></strong>: 소송 사건별 기일 관리, 판결 및 분쟁 처리 히스토리 관리</li></ul><h2 id="ibs의-의미-및-지향점" tabindex="-1">IBS의 의미 및 지향점 <a class="header-anchor" href="#ibs의-의미-및-지향점" aria-label="Permalink to &quot;IBS의 의미 및 지향점&quot;">​</a></h2><ul><li><strong>IBS (Intelligent Business System)</strong>: 단순한 데이터 기록 프로그램을 넘어, 비즈니스 데이터와 사람의 협업을 연결하는 지능형 업무 플랫폼을 의미합니다.</li><li><strong>우리의 지향점</strong>: 반복적인 수기 관리 업무를 자동화하여, 디벨로퍼와 본사 임직원이 사업의 본질인 <strong>기획, 분석, 그리고 최선의 의사결정</strong>에 집중할 수 있는 환경을 만들어 갑니다.</li></ul><h2 id="빠른-시작" tabindex="-1">빠른 시작 <a class="header-anchor" href="#빠른-시작" aria-label="Permalink to &quot;빠른 시작&quot;">​</a></h2><ul><li>처음 방문하셨다면 **<a href="/intro/getting-started.html">시작하기 가이드</a>**를 통해 초기 설정 및 기본 사용법을 확인하세요.</li><li>프로젝트 현황을 한눈에 파악하는 방법은 **<a href="/intro/dashboard.html">대시보드 가이드</a>**를 참고하세요.</li></ul>',21))])}const b=o(u,[["render",E]]);export{p as __pageData,b as default};
